 if($artifact.Count -ne 1 -or $meta.repo_commit -ne $sha -or (Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant() -ne $artifact[0].sha256){throw 'Safety executable mismatch'}
 $spec.build_provenance_sha256=(Get-FileHash $metaPath -Algorithm SHA256).Hash.ToLowerInvariant();$spec.executable=$exe;$spec.arguments=@(if($Action -eq 'audit-test'){'--absolute-admission-audit'}elseif($Action -eq 'correction-test'){'--prepared-correction'}elseif($Action -eq 'bound-test'){'--absolute-product-hipblaslt'}else{'--small'});$timeout=120

