 $reports=@([IO.File]::ReadAllLines((Join-Path $recordDir 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 $markers=@([IO.File]::ReadAllLines((Join-Path $recordDir 'product.stderr.log'))|Where-Object {$_.StartsWith('BATCH_MARK prefill_hipblaslt_producer ')})
 if($Action -eq 'audit-test'){
