  if($cases.Count -ne 4 -or @($cases|Where-Object {-not $_.redzones_pass -or -not $_.immutable_inputs_and_outputs -or $_.changed_bf16_endpoints -eq 0}).Count){throw 'Admission audit detector controls failed'}
 }elseif($Action -eq 'bound-test'){
  $cases=@($reports|Where-Object {$_.kind -eq 'absolute_product_matrix_bound'})
  if($cases.Count -ne 12 -or @($cases|Where-Object {$_.underestimates -ne 0 -or -not $_.redzones_pass -or -not $_.inputs_immutable}).Count){throw 'Resident absolute product bound failed'}
 }elseif($Action -eq 'correction-test'){
  $cases=@($reports|Where-Object {$_.type -eq 'correction_case'})
  $prepared=@([IO.File]::ReadAllLines((Join-Path $recordDir 'product.stderr.log'))|Where-Object {$_.StartsWith('BATCH_MARK hawkeye_prepared_operands ')})
  if($cases.Count -ne 4 -or $prepared.Count -ne 4 -or @($cases|Where-Object {$_.bf16_reference_mismatches -ne 0 -or -not $_.redzones_pass -or -not $_.mixed_row_fallback -or $_.absolute_product_bound}).Count){throw 'Prepared projection integration boundary failed'}
 }elseif($Action -eq 'safety-test'){
  $cases=@($reports|Where-Object {$_.type -eq 'projection_case'})
  if($cases.Count -ne 8 -or $markers.Count -ne 8 -or @($cases|Where-Object {$_.bf16_reference_mismatches -ne 0 -or -not $_.redzones_pass}).Count){throw 'Native producer safety boundary failed'}
 }else{
  $cases=@($reports|Where-Object {$_.type -eq 'real_qkv_result'})
  if($cases.Count -ne 1 -or $markers.Count -ne 1 -or $cases[0].bf16_mismatches -ne 0 -or $cases[0].elements -ne 58728448 -or -not $cases[0].redzones_pass -or -not $cases[0].inputs_immutable){throw 'Original QKV boundary failed'}
 }
}

